const row = $input.first().json;

const data = row.data_intake || {};
const funnel = row.interview_funnel || {};
const signals = row.signal_summary || {};
const bottlenecks = row.bottlenecks || {};
const themes = Array.isArray(row.repeated_themes) ? row.repeated_themes : [];

function n(value) {
  return value === null || value === undefined ? 0 : Number(value);
}

function display(value) {
  return String(value ?? 'unknown')
    .replace(/_/g, ' ')
    .replace(/[\r\n]+/g, ' ')
    .replace(/[\*\[\]]/g, '')
    .trim();
}

function listTop(items, labelKey = 'signal_name') {
  if (!Array.isArray(items) || items.length === 0) return 'none';
  return items.slice(0, 3).map(item => display(item[labelKey] || item.theme || 'unknown') + ' (' + item.count + ')').join(', ');
}

function statusLine(statusCounts) {
  if (!statusCounts || Object.keys(statusCounts).length === 0) return 'none';
  return Object.entries(statusCounts).map(([key, value]) => display(key) + ': ' + value).join(', ');
}

function stageLine(stageCounts) {
  const stages = ['new','waiting_q1','waiting_q2','waiting_q3','waiting_q4','analysis','completed'];
  const counts = stageCounts || {};
  return stages.map(stage => display(stage) + ': ' + (counts[stage] ?? 0)).join(', ');
}

const topToday = Array.isArray(signals.top_signal_name_today) ? signals.top_signal_name_today : [];
const signalOfDay = display(topToday[0]?.signal_name || 'not enough data');
const repeatedThemes = listTop(themes, 'theme');

const bottleneckPairs = Object.entries(bottlenecks).map(([key, value]) => [key, n(value)]).sort((a, b) => b[1] - a[1]);
const mainBottleneck = bottleneckPairs.find(([, value]) => value > 0);
const mainBottleneckText = mainBottleneck ? display(mainBottleneck[0]) + ': ' + mainBottleneck[1] : 'no visible bottleneck';

const lines = [
  'BrainCoach Intelligence Monitor MVP-1',
  new Date().toISOString(),
  '',
  '1. Data Intake',
  '- tracker entries total: ' + n(data.tracker_entries_total),
  '- tracker entries today: ' + n(data.tracker_entries_today),
  '- tracker entries last 24h: ' + n(data.tracker_entries_last_24h),
  '- observations total: ' + n(data.observations_total),
  '- observations today: ' + n(data.observations_today),
  '- signal candidates total: ' + n(data.signal_candidates_total),
  '- signal candidates today: ' + n(data.signal_candidates_today),
  '',
  '2. Interview Funnel',
  '- parent interviews total: ' + n(funnel.parent_interviews_total),
  '- started: ' + n(funnel.started),
  '- in progress: ' + n(funnel.in_progress),
  '- completed: ' + n(funnel.completed),
  '- abandoned: ' + n(funnel.abandoned),
  '- active conversations: ' + stageLine(funnel.active_conversations_by_stage),
  '',
  '3. Signals',
  '- top signal today: ' + listTop(signals.top_signal_name_today),
  '- top signal all time: ' + listTop(signals.top_signal_name_all_time),
  '- average confidence: ' + (signals.average_confidence ?? 'n/a'),
  '- low confidence count: ' + n(signals.low_confidence_count),
  '- statuses: ' + statusLine(signals.candidate_status_counts),
  '',
  '4. Bottlenecks',
  '- observations without signal candidates: ' + n(bottlenecks.observations_without_signal_candidates),
  '- signal candidates without observation id: ' + n(bottlenecks.signal_candidates_without_observation_id),
  '- conversations stuck over 6h: ' + n(bottlenecks.conversations_stuck_over_6h),
  '- interviews started but no responses: ' + n(bottlenecks.interviews_started_no_responses),
  '- errors today: ' + n(bottlenecks.errors_today),
  '',
  '5. Daily Intelligence Draft',
  '- Today the system is collecting: ' + n(data.tracker_entries_today) + ' tracker entries, ' + n(data.observations_today) + ' observations, ' + n(data.signal_candidates_today) + ' signal candidates.',
  '- Signal of the day: ' + signalOfDay + '.',
  '- Repeating themes: ' + repeatedThemes + '.',
  '- Possible bottleneck: ' + mainBottleneckText + '.',
  '- Manual review: inspect low confidence candidates, stuck conversations, and observation to signal gaps.'
];

return [{
  json: {
    report_text: lines.join('\n'),
    chat_id: 'REPLACE_WITH_TELEGRAM_CHAT_ID',
    run_at: row.run_at,
    read_only: true
  }
}];
